"""Pricing rules for the storefront."""


def apply_discount(value: float) -> float:
    return value * 0.9


def list_price(value: float) -> float:
    return apply_discount(value) + 5

"""Legacy helper kept for old callers; unrelated to the storefront rate."""


def apply_discount(value: float) -> float:
    return value * 0.5

"""Runtime-resolved pricing call."""

import pricing


def dynamic_discount(value: float) -> float:
    fn = getattr(pricing, "apply_discount")
    return fn(value)

"""Metric buckets; unrelated to the storefront discount."""

HISTOGRAM_BUCKETS = [90, 900, 9000]


def bucket(value: float) -> int:
    for bound in HISTOGRAM_BUCKETS:
        if value <= bound:
            return bound
    return HISTOGRAM_BUCKETS[-1]

"""Shipping rates; unrelated to the storefront discount."""

BASE_RATE_BPS = 1000  # shipping, not pricing


def shipping_fee(weight_grams: int) -> int:
    return max(500, weight_grams * BASE_RATE_BPS // 1000)

